window.futvizVista("xg-vs-goles-90","<div class=\"rx-mount\" data-rx=\"scatter\" data-rx-id=\"xg-vs-goles-90\" style=\"min-height:520px\"></div><script>(window.futvizVistas=window.futvizVistas||{})[\"xg-vs-goles-90\"]={\"id\":\"xg-vs-goles-90\",\"titulo\":\"xG vs. goles por 90'\",\"bajada\":\"Sobre la diagonal marc\u00f3 m\u00e1s que su xG; a la derecha de la l\u00ednea, el 30% con m\u00e1s xG.\",\"pregunta\":\"\u00bfQui\u00e9n genera m\u00e1s ocasiones y qui\u00e9n las convierte?\",\"tabla\":\"jugadores\",\"entidad\":\"jugadores\",\"x\":{\"col\":\"npxg90\",\"label\":\"xG sin penales por 90'\",\"corto\":\"xG por 90'\",\"dec\":2},\"y\":{\"col\":\"npg90\",\"label\":\"Goles sin penales por 90'\",\"corto\":\"Goles por 90'\",\"dec\":2},\"referencia\":{\"tipo\":\"diagonal\",\"dif\":\"goles \u2212 xG sin penales por 90'\",\"sobre\":\"Marcan m\u00e1s de lo esperado\",\"bajo\":\"Marcan menos de lo esperado\",\"decDif\":2,\"zonas\":{\"pct\":0.7,\"tr\":\"Muchas ocasiones y las meten\",\"br\":\"Muchas ocasiones pero las fallan\",\"bl\":\"Pocas ocasiones y las fallan\",\"tl\":\"Pocas ocasiones pero las meten\"}},\"requiere\":[\"npxg90\",\"npg90\"],\"subtitulo\":\"Jugadores con \u2265{min} min \u00b7 {temporada}\",\"filtros\":{\"posicion\":true,\"nivel\":true,\"sub21\":true},\"metricas\":[{\"id\":\"x\",\"etiqueta\":\"xG por 90'\",\"ayuda\":\"Ordenados por xG sin penales por 90'\"},{\"id\":\"y\",\"etiqueta\":\"Goles por 90'\",\"ayuda\":\"Ordenados por Goles sin penales por 90'\"}],\"queMirar\":\"Goles de cada jugador frente a su xG, por 90 minutos y sin penales.\\n- Horizontal: el xG, la probabilidad de gol de sus tiros seg\u00fan desde d\u00f3nde y c\u00f3mo remat\u00f3. Vertical: los goles que de verdad marc\u00f3.\\n- La diagonal es el punto en que marc\u00f3 justo lo que val\u00edan sus ocasiones: arriba lo supera y abajo se queda corto.\\n- La l\u00ednea vertical deja a su derecha al 30% con m\u00e1s xG de los jugadores que ves, los que m\u00e1s ocasiones generan.\",\"insight\":\"xg_goles_90\",\"fuente\":\"Understat\",\"colorPor\":[\"liga\",\"rendimiento\"],\"minimoPor90\":true,\"posicionesIni\":[\"Defensa\",\"Medio\",\"Delantero\"]};</script>");